cat > /tmp/test_api.js << 'EOF'
import express from 'express';
import { createApp } from './src/api.js';

const app = createApp(express);
const server = app.listen(3000, () => {
  console.log('Server started on port 3000');
});

// Test GET /v2/events
setTimeout(async () => {
  try {
    const res = await fetch('http://localhost:3000/v2/events', {
      headers: { 'Authorization': 'Bearer test-token' }
    });
    console.log('GET /v2/events - Status:', res.status);
    const body = await res.json();
    console.log('Response:', JSON.stringify(body));
  } catch (e) {
    console.error('GET /v2/events error:', e.message);
  }

  // Test POST /v2/events
  try {
    const res = await fetch('http://localhost:3000/v2/events', {
      method: 'POST',
      headers: { 
        'Authorization': 'Bearer test-token',
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({ name: 'test' })
    });
    console.log('POST /v2/events (no idempotency-key) - Status:', res.status);
    const body = await res.json();
    console.log('Response:', JSON.stringify(body));
  } catch (e) {
    console.error('POST /v2/events error:', e.message);
  }

  // Test POST /v2/events with idempotency-key
  try {
    const res = await fetch('http://localhost:3000/v2/events', {
      method: 'POST',
      headers: { 
        'Authorization': 'Bearer test-token',
        'Content-Type': 'application/json',
        'idempotency-key': 'test-key'
      },
      body: JSON.stringify({ name: 'test' })
    });
    console.log('POST /v2/events (with idempotency-key) - Status:', res.status);
    const body = await res.json();
    console.log('Response:', JSON.stringify(body));
  } catch (e) {
    console.error('POST /v2/events error:', e.message);
  }

  // Test GET /v1/events (documented endpoint)
  try {
    const res = await fetch('http://localhost:3000/v1/events', {
      headers: { 'Authorization': 'Bearer test-token' }
    });
    console.log('GET /v1/events (documented) - Status:', res.status);
  } catch (e) {
    console.error('GET /v1/events error:', e.message);
  }

  server.close();
  process.exit(0);
}, 500);
EOF
node /tmp/test_api.js 2>&1
